<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurpose;
use Civi\Lughauth\Shared\Event\PublicEvent;

class ConsentPurposeUpdateEvent extends ConsentPurposeEvent implements PublicEvent
{
    public function __construct(
        ConsentPurpose $payload,
        public readonly ConsentPurpose $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'consent-purpose.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
